// Black Soul Ultimate game server (Supabase Edge Function "bsu-game").
// Deployed with JWT verification OFF at the gateway because players sign in
// with Firebase; this file verifies the Firebase ID token itself.
import { Chess } from "npm:chess.js@1.4.0";
import { createRemoteJWKSet, jwtVerify } from "npm:jose@5.9.6";

/* Black Soul Ultimate — small chess engine for computer opponents.
 * Pure rules-engine consumer: it only ever picks from chess.js legal moves, so it
 * cannot make an illegal move. The same file runs in the browser (practice games)
 * and inside the server function (rewarded games). */
const VALUE = { p: 100, n: 320, b: 330, r: 500, q: 900, k: 0 };
const CENTER = [0, 4, 8, 12, 12, 8, 4, 0];

function evaluate(chess) {
    let score = 0;
    const board = chess.board();
    for (let r = 0; r < 8; r++) for (let f = 0; f < 8; f++) {
        const piece = board[r][f];
        if (!piece) continue;
        let v = VALUE[piece.type];
        if (piece.type === 'p') v += (piece.color === 'w' ? 6 - r : r - 1) * 6 + CENTER[f] / 2;
        else if (piece.type !== 'k' && piece.type !== 'r') v += CENTER[r] + CENTER[f];
        score += piece.color === 'w' ? v : -v;
    }
    return score;
}

const rank = san => (san.includes('#') ? 4 : 0) + (san.includes('=') ? 3 : 0) + (san.includes('x') ? 2 : 0) + (san.includes('+') ? 1 : 0);

function search(chess, depth, alpha, beta, budget) {
    const moves = chess.moves();
    const white = chess.turn() === 'w';
    if (!moves.length) return chess.isCheck() ? (white ? -100000 - depth : 100000 + depth) : 0;
    if (depth === 0 || budget.nodes <= 0) return evaluate(chess);
    moves.sort((a, b) => rank(b) - rank(a));
    let best = white ? -Infinity : Infinity;
    for (const san of moves) {
        budget.nodes--;
        chess.move(san);
        const score = search(chess, depth - 1, alpha, beta, budget);
        chess.undo();
        if (white) { if (score > best) best = score; if (best > alpha) alpha = best; }
        else { if (score < best) best = score; if (best < beta) beta = best; }
        if (alpha >= beta) break;
    }
    return best;
}

/** level 1 = easy, 2 = normal, 3 = hard. Returns {from, to, promotion} or null. */
function chooseMove(chess, level = 2, random = Math.random) {
    const moves = chess.moves({ verbose: true });
    if (!moves.length) return null;
    const pick = m => ({ from: m.from, to: m.to, promotion: m.promotion || undefined });
    if (level <= 1 && random() < 0.4) return pick(moves[Math.floor(random() * moves.length)]);
    const depth = level >= 3 ? 2 : 1;
    const budget = { nodes: level >= 3 ? 2600 : 1400 };
    const white = chess.turn() === 'w';
    let best = null, bestScore = white ? -Infinity : Infinity;
    moves.sort((a, b) => rank(b.san) - rank(a.san));
    for (const move of moves) {
        chess.move(move.san);
        let score = search(chess, depth, -Infinity, Infinity, budget) + (random() - 0.5) * 8;
        chess.undo();
        if (white ? score > bestScore : score < bestScore) { bestScore = score; best = move; }
    }
    return pick(best || moves[0]);
}

/** Facts about a move that was just played on `chess`, used for storage and narration. */
function describeMove(move, chess) {
    const flags = String(move.flags || '');
    let over = null, drawReason = null;
    if (chess.isCheckmate()) over = 'checkmate';
    else if (chess.isStalemate()) over = 'stalemate';
    else if (chess.isDraw()) {
        over = 'draw';
        drawReason = chess.isInsufficientMaterial() ? 'insufficient_material'
            : chess.isThreefoldRepetition() ? 'threefold_repetition' : 'fifty_move_rule';
    }
    return {
        san: move.san, from: move.from, to: move.to, piece: move.piece, color: move.color,
        captured: move.captured || null, promotion: move.promotion || null,
        castle: flags.includes('k') ? 'king' : flags.includes('q') ? 'queen' : null,
        en_passant: flags.includes('e'), check: chess.isCheck(), over, draw_reason: drawReason, fen: chess.fen()
    };
}

/* Black Soul Ultimate — server request handler.
 * Runs inside the bsu-game server function and, unchanged, inside the Node
 * tests. `db(uid, action, args)` calls public.bsu_api() with the service role.
 * The caller's identity (uid) always comes from a verified sign-in token, never
 * from the request body. */

/** Actions a browser may ask for. chess_commit is deliberately absent: a chess
 *  move is only stored after this file has checked it with the rules engine. */
const CLIENT_ACTIONS = new Set([
    'tick', 'eat', 'pray', 'permanent', 'quests', 'quest_accept', 'quest_progress', 'quest_complete',
    'save_put', 'save_get', 'rewards_claim', 'hall_poll', 'match_create', 'match_invite', 'match_respond',
    'match_state', 'match_leave', 'match_history', 'snakes_roll', 'chess_move', 'chess_action'
]);

const SQUARE = /^[a-h][1-8]$/;
const fail = (error, extra = {}) => ({ ok: false, error, ...extra });

function createHandler({ db, Chess, chooseMove, describeMove, limit = 300 }) {
    const hits = new Map();
    const allowed = uid => {
        const now = Date.now(), entry = hits.get(uid);
        if (!entry || now - entry.at > 60000) { hits.set(uid, { at: now, n: 1 }); if (hits.size > 5000) hits.clear(); return true; }
        return ++entry.n <= limit;
    };

    const rebuild = state => {
        const chess = new Chess();
        try { for (const san of state.history || []) chess.move(san); }
        catch { return new Chess(state.fen); }
        if (chess.fen() !== state.fen) return new Chess(state.fen);
        return chess;
    };

    /** If it is the computer's turn in a chess match, play its move. */
    async function computerReply(uid, view, since) {
        let current = view;
        for (let guard = 0; guard < 2; guard++) {
            const match = current.match;
            if (!current.ok || match.game !== 'chess' || match.status !== 'active') break;
            const mover = (current.players || []).find(p => p.seat === match.turn_seat);
            if (!mover?.is_ai) break;
            const chess = rebuild(match.state);
            const choice = chooseMove(chess, Number(match.state.ai_level) || 2);
            if (!choice) break;
            const move = chess.move(choice);
            const next = await db(uid, 'chess_commit', { ...describeMove(move, chess), match_id: match.id, version: match.version, seat: mover.seat, since });
            if (!next.ok) break;
            current = next;
        }
        return current;
    }

    async function chessMove(uid, args) {
        const since = Number(args.since) || 0;
        if (!SQUARE.test(String(args.from)) || !SQUARE.test(String(args.to))) return fail('bad_square');
        const promotion = ['q', 'r', 'b', 'n'].includes(args.promotion) ? args.promotion : undefined;
        const view = await db(uid, 'match_state', { match_id: args.match_id, since });
        if (!view.ok) return view;
        const match = view.match;
        if (match.game !== 'chess') return fail('wrong_game');
        if (match.status !== 'active') return fail('not_active');
        if (view.my_seat !== match.turn_seat) return fail('not_your_turn');
        const chess = rebuild(match.state);
        let move;
        try { move = chess.move({ from: args.from, to: args.to, promotion: promotion || 'q' }); }
        catch { return fail('illegal_move'); }
        if (!move) return fail('illegal_move');
        const committed = await db(uid, 'chess_commit', { ...describeMove(move, chess), match_id: match.id, version: match.version, seat: view.my_seat, since });
        if (!committed.ok) return committed;
        return computerReply(uid, committed, since);
    }

    return async function handle(uid, action, args) {
        if (typeof uid !== 'string' || !uid || uid.length > 128) return fail('unauthenticated');
        if (typeof action !== 'string' || !CLIENT_ACTIONS.has(action)) return fail('unknown_action');
        if (args === undefined || args === null) args = {};
        if (typeof args !== 'object' || Array.isArray(args)) return fail('bad_request');
        if (!allowed(uid)) return fail('slow_down');
        if (action === 'chess_move') return chessMove(uid, args);
        const result = await db(uid, action, args);
        if (result?.ok && (action === 'match_create' || action === 'match_state') && result.match?.game === 'chess' && result.match?.mode === 'ai') {
            return computerReply(uid, result, action === 'match_create' ? 0 : Number(args.since) || 0);
        }
        return result;
    };
}

const FIREBASE_PROJECT = Deno.env.get("BSU_FIREBASE_PROJECT") ?? "black-sword-ultimate-43c4d";
const SUPABASE_URL = Deno.env.get("SUPABASE_URL") ?? "";
const SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
const JWKS = createRemoteJWKSet(new URL("https://www.googleapis.com/service_accounts/v1/jwk/securetoken@system.gserviceaccount.com"));
const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, content-type",
  "Access-Control-Allow-Methods": "POST, GET, OPTIONS",
  "Access-Control-Max-Age": "86400",
};
const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...CORS, "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" } });

async function db(uid: string, action: string, args: unknown) {
  const response = await fetch(SUPABASE_URL + "/rest/v1/rpc/bsu_api", {
    method: "POST",
    headers: { apikey: SERVICE_KEY, Authorization: "Bearer " + SERVICE_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ p_uid: uid, p_action: action, p_args: args ?? {} }),
  });
  if (!response.ok) throw new Error("database " + response.status);
  return await response.json();
}

const handle = createHandler({ db, Chess, chooseMove, describeMove });

Deno.serve(async (request: Request) => {
  if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: CORS });
  if (request.method === "GET") {
    // Health check: proves the function is up and can reach the database rules,
    // without exposing any player data.
    try {
      const probe = await db("health-check", "health", {});
      return json({ ok: true, service: "bsu-game", database: probe?.error === "unknown_action" });
    } catch (_error) {
      return json({ ok: true, service: "bsu-game", database: false });
    }
  }
  if (request.method !== "POST") return json({ ok: false, error: "method_not_allowed" }, 405);
  const header = request.headers.get("authorization") ?? "";
  const token = header.toLowerCase().startsWith("bearer ") ? header.slice(7).trim() : "";
  if (!token) return json({ ok: false, error: "unauthenticated" }, 401);
  let uid = "";
  try {
    const { payload } = await jwtVerify(token, JWKS, {
      issuer: "https://securetoken.google.com/" + FIREBASE_PROJECT,
      audience: FIREBASE_PROJECT,
      algorithms: ["RS256"],
    });
    uid = typeof payload.sub === "string" ? payload.sub : "";
  } catch (_error) {
    return json({ ok: false, error: "unauthenticated" }, 401);
  }
  if (!uid) return json({ ok: false, error: "unauthenticated" }, 401);
  let body: { action?: unknown; args?: unknown };
  try {
    const text = await request.text();
    if (text.length > 1600000) return json({ ok: false, error: "too_large" }, 413);
    body = JSON.parse(text);
  } catch (_error) {
    return json({ ok: false, error: "bad_request" }, 400);
  }
  try {
    return json(await handle(uid, body?.action as string, body?.args));
  } catch (_error) {
    return json({ ok: false, error: "server_error" }, 500);
  }
});
